**Plan**

`login` in `src/api/routes.ts:11` starts a session as `createSession(user.id)` — i.e. one positional `userId` arg, no options object, and it keeps the returned session object. So refresh does `createSession(current.userId)`, reusing the `Session` type and `.ts` extension import style.

**File 1 — `src/auth/refresh.ts`**
```ts
import { createSession, getSession, revokeSession, type Session } from "./session.ts";

/** Rotate a session token: revoke the old one and start a fresh one for the same user. */
export function refreshSession(token: string): Session | undefined {
  const current = getSession(token);
  if (!current) return undefined;
  revokeSession(current.token);
  return createSession(current.userId);
}
```

**File 2 — `test/refresh.test.ts`** (mirrors `test/session.test.ts`: `node:test`, `beforeEach(resetSessions)`)
```ts
import { test, beforeEach } from "node:test";
import assert from "node:assert/strict";
import { refreshSession } from "../src/auth/refresh.ts";
import { createSession, getSession, resetSessions } from "../src/auth/session.ts";

beforeEach(() => resetSessions());

test("refreshSession issues a new token for the same user and drops the old one", () => {
  const old = createSession("u_1");
  const refreshed = refreshSession(old.token);
  assert.notEqual(refreshed, undefined);
  assert.equal(refreshed?.userId, "u_1");
  assert.notEqual(refreshed?.token, old.token);
  assert.equal(getSession(old.token), undefined);
  assert.equal(getSession(refreshed?.token ?? "")?.userId, "u_1");
});

test("refreshSession returns undefined for an unknown token", () => {
  assert.equal(refreshSession("nope"), undefined);
});
```

Two files only, no edits to existing files. `npm test` and `npm run typecheck` will verify. Say the word and I'll create them.
